import { definePrimitive, dispatch, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

type Attachment = {
  id: string
  name: string
  kind: "image" | "file"
  src: string
  srcDark?: string
  thumbnail?: string
  thumbnailDark?: string
  alt: string
  href?: string
  /** Bytes. */
  size?: number
  mimeType?: string
}

type AttachmentOpenReason = "item-press" | "imperative"

type AttachmentsOptions = {
  attachments?: readonly Attachment[]
  /** Runs before an attachment opens; `details.cancel()` keeps it closed. */
  onOpen?: (attachment: Attachment, details: ChangeDetails<AttachmentOpenReason>) => void
  /** What opening does once `onOpen` allowed it: the component shows an image or follows a file's link. */
  open?: (attachment: Attachment, event: Event | undefined) => void
}

function reasonOf(options: unknown): { reason: AttachmentOpenReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<AttachmentOpenReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const attachments = definePrimitive({
  name: "attachments",
  options: { attachments: "value", onOpen: "callback", open: "value" },
  state: (options: AttachmentsOptions) => ({ count: options.attachments?.length ?? 0 }),
  sync: (options) => ({ count: options.attachments?.length ?? 0 }),
  api: (context) => {
    const list = () => context.options().attachments ?? []
    return {
      // The agent bridge passes arguments unchecked.
      openAttachment(id: unknown, options?: ChangeOptions<AttachmentOpenReason>) {
        const attachment = list().find((candidate) => candidate.id === id)
        if (!attachment) {
          const ids = list().map((candidate) => candidate.id)
          throw new RangeError(`No attachment "${String(id)}". Attachments: ${ids.join(", ")}.`)
        }
        const details = reasonOf(options)
        if (dispatch(context, "onOpen", attachment, details)) return false
        context.options().open?.(attachment, details.event)
        return true
      },
      entries: () => list().map((attachment) => ({ value: attachment.id, label: attachment.name })),
    }
  },
  slots: (slot) => ({
    root: slot({ role: "group", attrs: (state) => ({ "data-count": String(state.count) }) }),
  }),
  agent: { actions: ["openAttachment"], items: (api) => api.entries() },
})

export { attachments }
export type { Attachment, AttachmentOpenReason, AttachmentsOptions }

"use client"

import { Button } from "@ui-sdk/react/button"
import type { ComponentProps, MouseEvent } from "react"
import { FileIcon } from "lucide-react"

import type { Attachment } from "@/components/ui/attachments-primitive"
import { Link } from "@/components/ui/link"
import { ThemedImage } from "@/components/ui/themed-image"
import { useLocale } from "@/lib/locale"
import { cn } from "@/lib/utils"

// UI SDK's Button keeps its own data-slot over a prop; the rendered element's props win.
function slotted(props: ComponentProps<"button">) {
  return <button {...props} data-slot="attachment-thumb" />
}

type AttachmentSize = "sm" | "md"

const units = ["byte", "kilobyte", "megabyte", "gigabyte", "terabyte"] as const

/** A byte count in the locale's words for the largest fitting unit, like "2.4 MB". */
function formatFileSize(bytes: number, locale?: string) {
  let value = bytes
  let unit = 0
  while (value >= 1000 && unit < units.length - 1) {
    value /= 1000
    unit++
  }
  return new Intl.NumberFormat(locale, {
    style: "unit",
    unit: units[unit],
    unitDisplay: "short",
    maximumFractionDigits: unit === 0 ? 0 : 1,
  }).format(value)
}

function fileType(attachment: Attachment) {
  const extension = /\.([a-z0-9]{1,5})$/iu.exec(attachment.name)?.[1]
  return (extension ?? attachment.mimeType?.split("/")[1] ?? "").toUpperCase()
}

const focusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"

const sizeClassNames = { sm: "h-12", md: "h-20" } satisfies Record<AttachmentSize, string>

type AttachmentThumbProps = {
  attachment: Attachment
  size?: AttachmentSize
  /** Runs on a press; `event.preventDefault()` stops a file's link from opening. Without it, an image is static. */
  onOpen?: (attachment: Attachment, event: MouseEvent<HTMLElement>) => void
  /** The accessible name of an image's button. */
  openLabel?: (name: string) => string
  locale?: string
  className?: string
}

function FileTile({ size }: { size: AttachmentSize }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "flex shrink-0 items-center justify-center rounded-control bg-muted text-muted-foreground",
        size === "sm" ? "size-8 [&_svg]:size-4" : "size-12 [&_svg]:size-5",
      )}
    >
      <FileIcon />
    </span>
  )
}

const defaultOpenLabel = (name: string) => `Open ${name}`

function AttachmentThumb({
  attachment,
  size = "md",
  onOpen,
  openLabel = defaultOpenLabel,
  locale: localeProp,
  className,
}: AttachmentThumbProps) {
  const locale = useLocale(localeProp)
  const shared = {
    "data-slot": "attachment-thumb",
    "data-kind": attachment.kind,
    "data-size": size,
    "data-attachment-id": attachment.id,
  }

  if (attachment.kind === "image") {
    const image = (
      <ThemedImage
        src={attachment.thumbnail ?? attachment.src}
        srcDark={attachment.thumbnailDark ?? attachment.srcDark}
        alt={onOpen ? "" : attachment.alt}
        loading="lazy"
        decoding="async"
        className="size-full object-cover"
      />
    )
    const box = cn(
      "relative shrink-0 overflow-hidden rounded-lg border bg-muted",
      size === "sm" ? "size-12" : "aspect-4/3 h-20",
      className,
    )
    if (!onOpen) {
      return (
        <span {...shared} className={box}>
          {image}
        </span>
      )
    }
    return (
      <Button
        {...shared}
        render={slotted}
        aria-label={openLabel(attachment.name)}
        title={attachment.name}
        onClick={(event) => onOpen(attachment, event)}
        className={cn(box, "touch-target cursor-pointer transition-colors hover:border-ring", focusRing)}
      >
        {image}
      </Button>
    )
  }

  const meta = [fileType(attachment), attachment.size === undefined ? "" : formatFileSize(attachment.size, locale)]
    .filter(Boolean)
    .join(" · ")
  const chip = cn(
    "flex max-w-64 shrink-0 items-center gap-inline rounded-lg border bg-card/(--glass-opacity) px-inset-item text-start text-card-foreground",
    // oxlint-disable-next-line shadcn/require-static-classes -- one of two static heights, picked by size
    sizeClassNames[size],
    className,
  )
  const content = (
    <>
      <FileTile size={size} />
      <span className="flex min-w-0 flex-col">
        <span data-slot="attachment-name" className="truncate text-body-sm font-medium">
          {attachment.name}
        </span>
        {meta && <span className="truncate text-caption text-muted-foreground">{meta}</span>}
      </span>
    </>
  )
  const pressable = cn(
    chip,
    "touch-target cursor-pointer transition-colors hover:bg-accent hover:text-accent-foreground",
    focusRing,
  )

  if (attachment.href) {
    return (
      <Link
        {...shared}
        variant="plain"
        href={attachment.href}
        target="_blank"
        rel="noreferrer"
        title={attachment.name}
        onClick={onOpen && ((event) => onOpen(attachment, event))}
        className={pressable}
      >
        {content}
      </Link>
    )
  }
  if (onOpen) {
    return (
      <Button
        {...shared}
        render={slotted}
        title={attachment.name}
        onClick={(event) => onOpen(attachment, event)}
        className={pressable}
      >
        {content}
      </Button>
    )
  }
  return (
    <span {...shared} className={chip}>
      {content}
    </span>
  )
}

export { AttachmentThumb, formatFileSize }
export type { AttachmentSize, AttachmentThumbProps }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { Button } from "@ui-sdk/react/button"
import { usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { useMemo, useRef, useState } from "react"
import { flushSync } from "react-dom"

import {
  AttachmentThumb,
  type AttachmentSize,
  formatFileSize,
  type AttachmentThumbProps,
} from "@/components/ui/attachment-thumb"
import {
  attachments as attachmentsPrimitive,
  type Attachment,
  type AttachmentOpenReason,
} from "@/components/ui/attachments-primitive"
import { Lightbox, type LightboxItem, type LightboxLabels } from "@/components/ui/lightbox"
import { cn } from "@/lib/utils"

type AttachmentLabels = {
  /** The accessible name of an image's button. */
  open: (name: string) => string
  /** The accessible name of the "+N" button that shows the rest. */
  more: (count: number) => string
  lightbox?: Partial<LightboxLabels>
}

const attachmentLabels: AttachmentLabels = {
  open: (name) => `Open ${name}`,
  more: (count) => `Show ${count} more attachments`,
}

type AttachmentStripProps = Omit<PartProps<"div">, "children" | "onSelect"> & {
  attachments: readonly Attachment[]
  /** Runs before an attachment opens, for a person or an agent; `details.cancel()` keeps it closed. */
  onOpen?: (attachment: Attachment, details: ChangeDetails<AttachmentOpenReason>) => void
  /** Shows this many, then a "+N" button for the rest. */
  max?: number
  size?: AttachmentSize
  labels?: Partial<AttachmentLabels>
  locale?: string
  /** Names the strip, for screen readers and agents. */
  "aria-label": string
}

const focusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"

// Data attributes aren't in the part's prop type, so they come in through a spread.
function rootAttributes(size: AttachmentSize) {
  return { "data-slot": "attachment-strip", "data-size": size }
}

function AttachmentStrip({
  attachments,
  onOpen,
  max,
  size = "md",
  labels: labelOverrides,
  locale,
  className,
  ...props
}: AttachmentStripProps) {
  const labels = { ...attachmentLabels, ...labelOverrides }
  const list = useRef<HTMLUListElement>(null)
  const [expanded, setExpanded] = useState(false)
  const [viewer, setViewer] = useState({ open: false, index: 0, id: "" })
  const images = useMemo<LightboxItem[]>(
    () =>
      attachments
        .filter((attachment) => attachment.kind === "image")
        .map(({ id, src, srcDark, alt, name, href }) => ({ id, src, srcDark, alt, name, href })),
    [attachments],
  )

  const handle = usePrimitive(attachmentsPrimitive, {
    attachments,
    onOpen,
    open: (attachment, event) => {
      if (attachment.kind === "image") {
        setViewer({ open: true, index: images.findIndex((image) => image.id === attachment.id), id: attachment.id })
      } else if (!event && attachment.href) {
        globalThis.open(attachment.href, "_blank", "noopener,noreferrer")
      }
    },
  })

  const hidden = max !== undefined && !expanded ? Math.max(attachments.length - max, 0) : 0
  const shown = hidden > 0 ? attachments.slice(0, max) : attachments

  const children = (
    <>
      <ul
        ref={list}
        data-slot="attachment-list"
        className="-m-inline flex min-w-0 items-center gap-items overflow-x-auto overscroll-x-contain p-inline"
      >
        {shown.map((attachment) => (
          <li key={attachment.id} className="flex shrink-0">
            <AttachmentThumb
              attachment={attachment}
              size={size}
              locale={locale}
              openLabel={labels.open}
              onOpen={(_, event) => {
                const opened = handle.api.openAttachment(attachment.id, {
                  reason: "item-press",
                  event: event.nativeEvent,
                })
                if (!opened) event.preventDefault()
              }}
            />
          </li>
        ))}
        {hidden > 0 && (
          <li className="flex shrink-0">
            <Button
              render={(part) => <button {...part} data-slot="attachment-more" />}
              aria-label={labels.more(hidden)}
              onClick={() => {
                flushSync(() => setExpanded(true))
                const first = attachments[max ?? 0]
                list.current
                  ?.querySelector<HTMLElement>(`[data-attachment-id="${CSS.escape(first?.id ?? "")}"]`)
                  ?.focus()
              }}
              className={cn(
                "touch-target flex shrink-0 cursor-pointer items-center justify-center rounded-lg border border-dashed bg-muted/(--glass-opacity) px-inset-item text-body-sm font-medium text-muted-foreground tabular-nums transition-colors hover:bg-accent hover:text-accent-foreground",
                size === "sm" ? "h-12 min-w-12" : "h-20 min-w-20",
                focusRing,
              )}
            >
              +{hidden}
            </Button>
          </li>
        )}
      </ul>
      {images.length > 0 && (
        <Lightbox
          items={images}
          index={viewer.index}
          onIndexChange={(index) => setViewer((current) => ({ ...current, index }))}
          open={viewer.open}
          onOpenChange={(open) => setViewer((current) => ({ ...current, open }))}
          finalFocus={() =>
            list.current?.querySelector<HTMLElement>(`[data-attachment-id="${CSS.escape(viewer.id)}"]`) ?? undefined
          }
          labels={labels.lightbox}
        />
      )}
    </>
  )

  return usePart(
    handle,
    "root",
    {},
    { ...props, ...rootAttributes(size), className: cn("flex min-w-0", className), children },
    "div",
  )
}

export { AttachmentStrip, attachmentLabels }
export { AttachmentThumb, formatFileSize }
export type { AttachmentLabels, AttachmentStripProps }
export type { AttachmentSize, AttachmentThumbProps }
export type { Attachment, AttachmentOpenReason }
